Method.Source:
public SysMessageProcessorMaxBundleSize getMaxBundleSize()
{
    int maxBundleSize =  SalesParameters::find().MessageProcessorBatchTaskSize;

    return maxBundleSize ? maxBundleSize : DefaultBundleSize;
}

/// <summary>
/// to fix error cannot send message to the queue from external source
/// </summary>
/// <param name = "_messageType"></param>
/// <param name = "_companyId"></param>
/// <returns></returns>
public boolean canSendMessageUsingMessageService(SysMessageType _messageType, CompanyId _companyId)
{
    return true;
}
